"""Birth policy cannot be selected by templates, model arguments or edits."""
import pytest

from services.agent_runtime_policy import (
    AgentRuntimeParams, new_agent_parameters, preserve_runtime_version,
    runtime_behavior_version, runtime_context,
)


@pytest.mark.parametrize("value", [None, {}, {"runtime_behavior_version": 0}, {"runtime_behavior_version": True},
                                      {"runtime_behavior_version": "1"}, {"runtime_behavior_version": 2}])
def test_missing_and_untrusted_policy_is_legacy(value):
    assert runtime_behavior_version(value) == 0
    assert runtime_context(value) == {}


def test_schema_default_never_upgrades_old_nodes():
    assert AgentRuntimeParams().runtime_behavior_version == 0
    assert AgentRuntimeParams.model_json_schema()["properties"]["runtime_behavior_version"]["default"] == 0


def test_fresh_creation_gate_never_accepts_caller_policy(monkeypatch):
    monkeypatch.setenv("NEW_AGENT_RUNTIME_V1_ENABLED", "false")
    assert new_agent_parameters({"runtime_behavior_version": 1, "model": "x"}) == {"model": "x"}
    monkeypatch.setenv("NEW_AGENT_RUNTIME_V1_ENABLED", "true")
    assert new_agent_parameters({"runtime_behavior_version": 0, "model": "x"}) == {"model": "x", "runtime_behavior_version": 1}


@pytest.mark.parametrize("old", [{}, {"runtime_behavior_version": 0}, {"runtime_behavior_version": 1}])
def test_regular_edits_preserve_identity(old):
    proposed = {"runtime_behavior_version": 1 - old.get("runtime_behavior_version", 0), "model": "new"}
    saved = preserve_runtime_version(old, proposed)
    assert runtime_behavior_version(saved) == runtime_behavior_version(old)
    assert ("runtime_behavior_version" in saved) == ("runtime_behavior_version" in old)
    assert saved["model"] == "new"


def test_only_v1_payloads_gain_a_new_key():
    assert runtime_context({}) == {}
    assert runtime_context({"runtime_behavior_version": 1}) == {"runtime_behavior_version": 1}


def test_all_real_agent_roots_advertise_creation_without_schema_upgrade():
    from models.node_metadata import NODE_METADATA
    from services.node_registry import get_node_class
    from services.plugin.base import locked_tool_fields
    found = set()
    for kind in NODE_METADATA:
        cls = get_node_class(kind)
        if cls and getattr(cls, "component_kind", "") == "agent" and issubclass(cls.Params, AgentRuntimeParams):
            found.add(kind)
            assert cls.Params.model_fields["runtime_behavior_version"].default == 0
            assert NODE_METADATA[kind]["uiHints"]["creationParameters"] == {"runtime_behavior_version": 1}
            assert "runtime_behavior_version" in locked_tool_fields(cls)
    assert {"aiAgent", "chatAgent", "coding_agent", "browser_agent", "claude_code_agent", "codex_agent", "mobile_use_agent"} <= found


def test_fresh_finalizer_never_stamps_an_existing_member(monkeypatch):
    from services.agent_runtime_policy import stamp_new_graph_parameters
    monkeypatch.setenv("NEW_AGENT_RUNTIME_V1_ENABLED", "true")
    graph = {"nodes": [{"id": "old", "type": "aiAgent"}, {"id": "new", "type": "aiAgent"},
        {"id": "old-skill", "type": "masterSkill"}, {"id": "new-skill", "type": "masterSkill"}],
        "edges": [{"source": "old-skill", "target": "old", "targetHandle": "input-skill"},
                  {"source": "new-skill", "target": "new", "targetHandle": "input-skill"}]}
    parameters = {key: {} for key in ("old", "new", "old-skill", "new-skill")}
    stamp_new_graph_parameters(graph, parameters, {"new", "new-skill"})
    assert parameters["old"] == parameters["old-skill"] == {}
    assert parameters["new"]["runtime_behavior_version"] == parameters["new-skill"]["runtime_behavior_version"] == 1


@pytest.mark.parametrize("version", [0, 1])
def test_new_skill_holder_uses_existing_target_policy(monkeypatch, version):
    from services.agent_runtime_policy import prepare_new_agent_additions
    from services.graph_build import GraphAdditions, NewNode, skill_edge
    monkeypatch.setenv("NEW_AGENT_RUNTIME_V1_ENABLED", "true")
    batch = GraphAdditions(nodes=[NewNode("holder", "masterSkill", "Skills", {})],
        edges=[skill_edge("holder", "existing-agent")])
    prepared = prepare_new_agent_additions(batch, {"existing-agent": {"runtime_behavior_version": version}})
    assert prepared.nodes[0].params.get("runtime_behavior_version", 0) == version

from services.workflow_migrations import normalize_legacy_android_toolkit


def _node(node_id, node_type):
    return {"id": node_id, "type": node_type, "data": {"label": node_id}}


def test_legacy_android_toolkit_becomes_direct_agent_tool_edges():
    nodes = [
        _node("battery", "batteryMonitor"),
        _node("location", "location"),
        _node("toolkit", "androidTool"),
        _node("android", "android_agent"),
        _node("custom", "aiAgent"),
    ]
    edges = [
        {"id": "a", "source": "battery", "target": "toolkit", "targetHandle": "input-main"},
        {"id": "b", "source": "location", "target": "toolkit", "target_handle": "input-main"},
        {"id": "c", "source": "toolkit", "target": "android", "targetHandle": "input-tools"},
        {"id": "d", "source": "toolkit", "target": "custom", "target_handle": "input-tools"},
    ]

    migrated_nodes, migrated_edges, params, warnings = normalize_legacy_android_toolkit(
        nodes, edges, {"toolkit": {"old": True}, "battery": {"action": "status"}}
    )

    assert "toolkit" not in {node["id"] for node in migrated_nodes}
    assert "toolkit" not in params
    assert params["battery"] == {"action": "status"}
    assert warnings == []
    assert {
        (edge["source"], edge["target"], edge["targetHandle"])
        for edge in migrated_edges
    } == {
        ("battery", "android", "input-tools"),
        ("battery", "custom", "input-tools"),
        ("location", "android", "input-tools"),
        ("location", "custom", "input-tools"),
    }


def test_migration_is_idempotent_and_deduplicates_direct_edges():
    nodes = [_node("battery", "batteryMonitor"), _node("toolkit", "androidTool"), _node("agent", "aiAgent")]
    edges = [
        {"source": "battery", "target": "toolkit"},
        {"source": "toolkit", "target": "agent", "targetHandle": "input-tools"},
        {"id": "direct", "source": "battery", "target": "agent", "targetHandle": "input-tools"},
    ]
    first = normalize_legacy_android_toolkit(nodes, edges)
    second = normalize_legacy_android_toolkit(first[0], first[1], first[2])

    assert first[:3] == second[:3]
    assert len(first[1]) == 1
    assert first[1][0]["id"] == "direct"


def test_orphan_toolkit_is_removed_with_warning_and_non_android_inputs_are_not_rewired():
    nodes = [_node("http", "httpRequest"), _node("toolkit", "androidTool")]
    edges = [{"source": "http", "target": "toolkit"}]

    migrated_nodes, migrated_edges, _, warnings = normalize_legacy_android_toolkit(nodes, edges)

    assert migrated_nodes == [nodes[0]]
    assert migrated_edges == []
    assert warnings and "without a valid destination agent" in warnings[0]

import pytest

from services.llm.schema import compile_tool_schema


def test_schema_compiler_inlines_pydantic_refs_without_mutating_input():
    schema = {
        "$defs": {
            "Location": {
                "type": "object",
                "properties": {"city": {"type": "string"}},
                "required": ["city"],
            }
        },
        "type": "object",
        "properties": {
            "location": {
                "$ref": "#/$defs/Location",
                "description": "Where to search",
            }
        },
    }

    compiled = compile_tool_schema(schema, provider="anthropic")
    assert "$defs" in schema
    assert "$defs" not in compiled
    assert compiled["properties"]["location"] == {
        "type": "object",
        "properties": {"city": {"type": "string"}},
        "required": ["city"],
        "description": "Where to search",
    }


def test_gemini_schema_normalizes_nullable_and_drops_unsupported_metadata():
    compiled = compile_tool_schema(
        {
            "type": "object",
            "properties": {
                "unit": {
                    "type": ["string", "null"],
                    "default": None,
                    "examples": ["celsius"],
                    "displayOptions": {"show": {"operation": ["convert"]}},
                    "placeholder": "celsius",
                    "rows": 3,
                },
                # Property names are data, not schema keywords. A
                # structure-aware filter must retain this field even though
                # the Gemini Schema model does not accept the ``default``
                # annotation keyword.
                "default": {
                    "type": "string",
                    "displayOptions": {"show": {"advanced": [True]}},
                },
                "tags": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "widget": "tags",
                        "displayOptions": {"show": {"advanced": [True]}},
                    },
                },
                "settings": {
                    "type": "object",
                    "additionalProperties": False,
                },
            },
        },
        provider="gemini",
    )
    unit = compiled["properties"]["unit"]
    assert unit == {"type": "string", "nullable": True}
    assert compiled["properties"]["default"] == {"type": "string"}
    assert compiled["properties"]["tags"] == {
        "type": "array",
        "items": {"type": "string"},
    }
    assert compiled["properties"]["settings"]["additionalProperties"] is False


def test_gemini_compiled_pydantic_ui_schema_is_accepted_by_sdk():
    """Regression: real Pydantic schemas must form a valid Gemini config."""

    from typing import Literal

    from google.genai import types
    from pydantic import BaseModel, Field

    class FileModifyParams(BaseModel):
        operation: str = "write"
        content: str = Field(
            default="",
            json_schema_extra={
                "displayOptions": {"show": {"operation": ["write"]}},
                "rows": 6,
                "placeholder": "File contents",
            },
        )
        replace_all: bool = Field(
            default=False,
            json_schema_extra={
                "displayOptions": {"show": {"operation": ["edit"]}},
                "hidden": True,
            },
        )
        memory: Literal[128, 256] = 128

    parameters = compile_tool_schema(
        FileModifyParams.model_json_schema(),
        provider="gemini",
    )
    config = types.GenerateContentConfig(
        tools=[
            {
                "function_declarations": [
                    {
                        "name": "file_modify",
                        "description": "Write or edit a file",
                        "parameters": parameters,
                    }
                ]
            }
        ]
    )

    declaration = config.tools[0].function_declarations[0]
    assert declaration.parameters_json_schema is None
    schema = declaration.parameters
    assert schema is not None
    assert set(schema.properties) == {
        "operation",
        "content",
        "replace_all",
        "memory",
    }
    assert schema.properties["memory"].enum == ["128", "256"]


def test_gemini_schema_preserves_literals_enums_and_nested_nullable_unions():
    compiled = compile_tool_schema(
        {
            "type": "object",
            "properties": {
                "operation": {
                    "type": "string",
                    "const": "lookup",
                },
                "options": {
                    "type": "object",
                    "properties": {
                        "mode": {
                            "anyOf": [
                                {"type": "string", "const": "fast"},
                                {"type": "null"},
                            ]
                        },
                        "unit": {
                            "type": "string",
                            "enum": ["celsius", "fahrenheit"],
                        },
                    },
                },
            },
        },
        provider="gemini",
    )

    assert compiled["properties"]["operation"] == {
        "type": "string",
        "enum": ["lookup"],
    }
    options = compiled["properties"]["options"]["properties"]
    assert options["mode"] == {
        "anyOf": [{"type": "string", "enum": ["fast"]}],
        "nullable": True,
    }
    assert options["unit"]["enum"] == ["celsius", "fahrenheit"]


def test_schema_compiler_rejects_external_and_recursive_refs():
    with pytest.raises(ValueError, match="Only local"):
        compile_tool_schema(
            {"$ref": "https://example.com/schema.json"},
            provider="openai",
        )

    recursive = {
        "$defs": {"Node": {"$ref": "#/$defs/Node"}},
        "$ref": "#/$defs/Node",
    }
    with pytest.raises(ValueError, match="Recursive"):
        compile_tool_schema(recursive, provider="openai")

